331	func TestReadVersionAndCorruptionRecovery(t *testing.T) {
332		a, dir := newTestArchive(t)
333		w := baseWorld(t)
334		r0, _ := a.Save("s", w)
335		cur, _ := a.Latest("s", []string{"v1"})
336		_, _ = w.Apply(Commit{Time: 1})
