582	// writeRawRecord 直接写入一条记录文件并返回其标识，供损坏/版本测试使用。
583	func writeRawRecord(t *testing.T, a *Archive, parent RecordID, first bool, st State) RecordID {
584		t.Helper()
585		id, err := newRecordID()
586		if err != nil {
587			t.Fatal(err)
588		}
589		env := &envelope{
590			Format:    archiveFormatVersion,
591			ID:        id,
592			Parent:    parent,
593			SlotFirst: first,
594			State:     st,
595		}
596		env.Checksum = computeChecksum(env)
597		if err := writeRecord(a.dir, env); err != nil {
598			t.Fatal(err)
599		}
600		return id
601	}
