func TestOverwrittenHistoryStillReadable(t *testing.T) {
	a, dir := newTestArchive(t)
	w := baseWorld(t)
	r0, err := a.Save("s", w)
	if err != nil {
		t.Fatal(err)
	}
	for i := 1; i <= 3; i++ {
		if _, err := w.Apply(Commit{Time: i}); err != nil {
			t.Fatal(err)
		}
		latest, err := a.Latest("s", []string{"v1"})
		if err != nil {
