// create_regression_test.go 针对 Create 本身的失败保障做回归：创建失败后
// 目录原有内容必须原样保留、本次新建的内容必须撤回，排除障碍后可在同一
// 路径继续创建。其余存档用例主要把成功创建当作准备步骤，这里补足创建
// 操作自身的成功与失败约定。
//
// 目录树中条目类型的编码：
//   - "dir/"            目录（空目录与非空目录都用同一形式，非空可由其子
//     条目推出）
//   - "file:<content>"  普通文件及其完整内容
func snapshotTree(t *testing.T, root string) []string {
	t.Helper()
	var got []string
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if path == root {
			return nil
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		switch {
		case d.IsDir():
			got = append(got, rel+"/")
		case d.Type().IsRegular():
			data, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			got = append(got, rel+":"+string(data))
		default:
			got = append(got, rel+":<special>")
		}
		return nil
	})
	if err != nil {
		t.Fatalf("遍历目录 %s: %v", root, err)
	}
	sort.Strings(got)
	return got
}

func assertTreeEqual(t *testing.T, root string, want []string) {
	t.Helper()
	got := snapshotTree(t, root)
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("目录内容不符:\n得到 %v\n想要 %v", got, want)
	}
}

func assertDirExists(t *testing.T, path string) {
	t.Helper()
	fi, err := os.Stat(path)
	if err != nil {
		t.Fatalf("目录应仍存在 %s: %v", path, err)
	}
	if !fi.IsDir() {
		t.Fatalf("%s 应仍是目录", path)
	}
}

func assertRegularFile(t *testing.T, path string) {
	t.Helper()
	fi, err := os.Stat(path)
	if err != nil {
		t.Fatalf("普通文件应保留 %s: %v", path, err)
	}
	if !fi.Mode().IsRegular() {
		t.Fatalf("%s 应仍是普通文件", path)
	}
}

// assertCreateFails 断言 Create 明确失败：返回非空错误但不返回句柄，错误
// 信息同时说明失败的操作与具体位置。wantSubs 中每一项都必须出现在错误
// 文本里（如“建立存档子目录”与被占用路径）。
func assertCreateFails(t *testing.T, dir string, wantSubs ...string) {
