// create_regression_test.go 针对 Create 本身的失败保障做回归：创建失败后
// 目录原有内容必须原样保留、本次新建的内容必须撤回，排除障碍后可在同一
// 路径继续创建。其余存档用例主要把成功创建当作准备步骤，这里补足创建
// 操作自身的成功与失败约定。
//
// 目录树中条目类型的编码：
//   - "dir/"            目录（空目录与非空目录都用同一形式，非空可由其子
//     条目推出）
//   - "file:<content>"  普通文件及其完整内容
func snapshotTree(t *testing.T, root string) []string {
	t.Helper()
	var got []string
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if path == root {
			return nil
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		switch {
		case d.IsDir():
			got = append(got, rel+"/")
		case d.Type().IsRegular():
			data, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			got = append(got, rel+":"+string(data))
		default:
			got = append(got, rel+":<special>")
		}
		return nil
	})
	if err != nil {
		t.Fatalf("遍历目录 %s: %v", root, err)
	}
	sort.Strings(got)
	return got
}

func assertTreeEqual(t *testing.T, root string, want []string) {
	t.Helper()
	got := snapshotTree(t, root)
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("目录内容不符:\n得到 %v\n想要 %v", got, want)
	}
}

